/* Basic reset */
* {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
}

html, body {
    height: 100%;
    font-family: Arial, sans-serif;
    background: #f0f4f7;
    display: flex;
    justify-content: center;
    align-items: center;
}

.container {
    background: #fff;
    padding: 2rem;
    border-radius: 10px;
    box-shadow: 0 4px 15px rgba(0,0,0,0.1);
    text-align: center;
    width: 90%;
    max-width: 400px;
}

.timer-display {
    font-size: 4rem;
    margin: 1rem 0;
    color: #2c3e50;
}

.session-type {
    font-size: 1.2rem;
    margin-bottom: 1rem;
    color: #34495e;
}

.controls button {
    padding: 0.5rem 1rem;
    margin: 0 0.3rem;
    font-size: 1rem;
    border: none;
    border-radius: 5px;
    cursor: pointer;
    transition: background 0.2s;
    background: #2980b9;
    color: #fff;
}
.controls button:hover {
    background: #1c5980;
}

.session-select {
    margin-top: 1rem;
}

.session-select select {
    padding: 0.3rem;
    font-size: 1rem;
}

/* Responsive */
@media (max-width: 480px) {
    .timer-display {
        font-size: 3rem;
    }
}
